const Api=function(){const inFlight=new Map;const DEDUPE_POST_ACTIONS=["getConversation","getCustomerInbox","getCustomerProfile","listCustomerOrders","listCustomerBookings","getUnreadCount","getVendorConversations"];function share(key,run){const existing=inFlight.get(key);if(existing)return existing;const promise=run().finally(()=>{if(inFlight.get(key)===promise)inFlight.delete(key)});inFlight.set(key,promise);return promise}function assertConfigured(){if(!APP_CONFIG.APPS_SCRIPT_URL||APP_CONFIG.APPS_SCRIPT_URL.indexOf("PASTE_YOUR")===0){throw new Error("This shop is not connected yet. Ask the site owner to finish setup (see README.md).")}}async function get(action,params){assertConfigured();const url=new URL(APP_CONFIG.APPS_SCRIPT_URL);url.searchParams.set("action",action);Object.entries(params||{}).forEach(([key,value])=>{if(value!==undefined&&value!==null)url.searchParams.set(key,value)});const href=url.toString();return share("GET "+href,async()=>{try{const res=await fetch(href,{method:"GET"});return await res.json()}catch(err){return{ok:false,error:"Network error - please check your connection and try again."}}})}async function post(action,payload){assertConfigured();const body=JSON.stringify(Object.assign({action:action},payload||{}));const send=async()=>{try{const res=await fetch(APP_CONFIG.APPS_SCRIPT_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:body});return await res.json()}catch(err){return{ok:false,error:"Network error - please check your connection and try again."}}};if(DEDUPE_POST_ACTIONS.indexOf(action)===-1)return send();return share("POST "+body,send)}return{get:get,post:post}}();